{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Integrative courses & cohort care</title>
  <meta name="description" content="A playful, practical blend of learning and care for people who want a sustainable path to feeling steadier. Cohort programs, single sessions, and an interactive session planner." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site-root">
  <svg class="bg-pattern" aria-hidden="true">
    <defs>
      <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
        <rect width="40" height="40" fill="#f8fbfa"></rect>
        <path d="M0 20 L40 20 M20 0 L20 40" stroke="#eef6f5" stroke-width="1"/>
      </pattern>
    </defs>
    <rect width="100%" height="100%" fill="url(#p)"></rect>
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/offerings.html">Offerings</a>
        <a href="/concerns.html">Concerns</a>
        <a href="/how-we-work.html">How We Work</a>
        <a href="/invest.html">Invest</a>
        <a href="/team.html">Team</a>
        <a class="cta" href="/book.html">Book a Visit</a>
      </nav>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero reveal">
      <div class="wrap hero-grid">
        <div class="hero-copy">
          <h1>{{TAGLINE}}</h1>
          <p class="lede">Take a small, thoughtful turn toward clearer days. We mix group learning with one-on-one support so you get practical moves that stick.</p>
          <p class="meta">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p><a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        </div>
        <aside class="planner-card" aria-labelledby="planner-title">
          <h2 id="planner-title">Session Planner</h2>
          <form id="planner-form">
            <label>Primary focus (short):
              <input name="focus" placeholder="sleep, digestion, stress, etc." required>
            </label>
            <label>One sentence about your routine:
              <input name="routine" placeholder="Morning, evening, work hours...">
            </label>
            <label>Biggest obstacle:
              <input name="obstacle" placeholder="Time, energy, symptoms...">
            </label>
            <label>Time you can commit weekly:
              <select name="time">
                <option>30 minutes</option>
                <option>1 hour</option>
                <option>2–3 hours</option>
              </select>
            </label>
            <fieldset>
              <legend>Preference</legend>
              <label><input type="radio" name="style" value="guided" checked> Hands-on plan</label>
              <label><input type="radio" name="style" value="learning"> Small-group learning</label>
            </fieldset>
            <div class="planner-actions">
              <button type="button" id="build-plan">Build plan</button>
              <button type="button" id="copy-plan">Copy summary</button>
            </div>
          </form>
          <label class="output-label">Plan Summary
            <textarea id="plan-output" readonly rows="6"></textarea>
          </label>
        </aside>
      </div>
    </section>

    <!-- Pillars (moved before myths for a different flow) -->
    <section class="pillars reveal">
      <div class="wrap">
        <h2>What we center</h2>
        <p class="sub">Three complementary threads that shape each cohort and session.</p>
        <div class="grid">
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" stroke="#6aa89e" fill="none" stroke-width="1.5"/></svg>
            <h3>Context-first</h3>
            <p>We begin with your day-to-day: where time is spent, what drains you, and where small shifts add up.</p>
          </article>
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h16" stroke="#7fb6b0" stroke-width="1.5"/></svg>
            <h3>Practical skillwork</h3>
            <p>Skills, not sermons. Simple experiments you can do alone or with the cohort between sessions.</p>
          </article>
          <article>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4" stroke="#9fd5cf" fill="none" stroke-width="1.5"/></svg>
            <h3>Shared learning</h3>
            <p>Small cohort runs let you learn with others and borrow ideas from real people in real lives.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- Myth vs Truth -->
    <section class="myth-truth reveal">
      <div class="wrap">
        <h2>Busting a few myths</h2>
        <ul class="myth-list">
          <li>
            <strong>Myth:</strong> You must overhaul your life to feel better.
            <p class="truth"><strong>Truth:</strong> Small, consistent experiments are how sustainable change happens.</p>
          </li>
          <li>
            <strong>Myth:</strong> Integrative care is only for extremes.
            <p class="truth"><strong>Truth:</strong> We support people with everyday friction just as much as complex conditions.</p>
          </li>
          <li>
            <strong>Myth:</strong> Group learning replaces personal care.
            <p class="truth"><strong>Truth:</strong> Cohorts amplify practical habits while individual sessions personalize them.</p>
          </li>
        </ul>
      </div>
    </section>

    <!-- Case notes -->
    <section class="case-notes reveal">
      <div class="wrap">
        <h2>Short case notes</h2>
        <p class="sub">Real sketches — anonymized and simplified to show what a plan looks like.</p>
        <ol>
          <li>
            <strong>Focus:</strong> Sleep consolidation.
            <p>Plan: Two-week bedroom hygiene + 3 evening rituals. Check-in at week 2; tweak timing. Outcome: steadier sleep onset for most participants.</p>
          </li>
          <li>
            <strong>Focus:</strong> Afternoon exhaustion.
            <p>Plan: Small meal timing experiment, 10-minute mid-day walk, and brief screen-breaks. Outcome: improved alertness in 10/12 cohort members.</p>
          </li>
        </ol>
        <p class="disclaimer">These are educational examples, not medical guarantees. For specific diagnoses, seek medical evaluation before changing treatment.</p>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq reveal">
      <div class="wrap">
        <h2>Frequently asked</h2>
        <div class="qa">
          <button class="q">Do I need a referral?</button>
          <div class="a">No referral required. We clarify scope and coordinate with primary care when appropriate.</div>
        </div>
        <div class="qa">
          <button class="q">Is this medical care?</button>
          <div class="a">It is integrative education and cohort-based care. We do not promise cures. Medical questions are referred back to clinicians as needed.</div>
        </div>
        <div class="qa">
          <button class="q">How long is a cohort?</button>
          <div class="a">Most cohorts run 6–8 weeks with weekly touchpoints plus resources you use between sessions.</div>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="final-cta reveal">
      <div class="wrap cta-wrap">
        <h2>Ready for a clear next step?</h2>
        <p>Join a friendly cohort or book a focused session — we’ll help you shape it into something you can actually do.</p>
        <p><a class="primary large" href="/book.html">Reserve a spot</a> <a class="ghost" href="/contact.html">Ask a question</a></p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <nav class="foot-nav">
        <a href="/privacy.html">Privacy</a>
        <a href="/terms.html">Terms</a>
        <a href="/sitemap.xml">Sitemap</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
