{"path":"assets/css/styles.css","content":"/* Minimal, playful-leaning styles */
:root{
  --bg:#ffffff;
  --ink:#14332f;
  --muted:#5e7b76;
  --accent:#7fb6b0;
  --radius:12px;
  --wrap:1100px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;background:var(--bg);color:var(--ink);line-height:1.45}
.wrap{max-width:var(--wrap);margin:0 auto;padding:2rem}
.bg-pattern{position:fixed;inset:0;z-index:-1;width:100%;height:100%;opacity:1}
.site-header{border-bottom:1px solid #eef6f5}
.site-header .wrap{display:flex;align-items:center;justify-content:space-between;padding:1rem 2rem}
.brand{font-weight:700;color:var(--ink);text-decoration:none}
.main-nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
.main-nav .cta{background:var(--accent);color:white;padding:.5rem .8rem;border-radius:8px;text-decoration:none}
.hero{padding:3rem 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:2rem;align-items:start}
.hero-copy h1{font-size:1.8rem;margin:0 0 .5rem}
.lede{color:var(--muted);margin:0 0 1rem}
.primary{display:inline-block;background:var(--accent);color:white;padding:.7rem 1rem;border-radius:10px;text-decoration:none}
.planner-card{background:#fff;border:1px solid #eef6f5;padding:1rem;border-radius:12px;box-shadow:0 6px 22px rgba(9,24,22,0.03)}
.planner-card h2{margin-top:0}
.planner-card label{display:block;font-size:.9rem;color:var(--muted);margin-bottom:.5rem}
.planner-card input, .planner-card select, .planner-card textarea{width:100%;padding:.5rem;border:1px solid #e6f0ed;border-radius:8px;margin-top:.35rem}
.planner-actions{display:flex;gap:.5rem;margin-top:.5rem}
.planner-actions button{flex:1;padding:.6rem;border-radius:8px;border:0;background:var(--accent);color:white}
.planner-actions #copy-plan{background:#fff;color:var(--accent);border:1px solid var(--accent)}
.pillars{padding:2rem 0}
.pillars .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1.2rem;margin-top:1rem}
.pillars article{background:#fff;border:1px solid #eef6f5;padding:1rem;border-radius:10px}
.icon{width:44px;height:44px;margin-bottom:.5rem;display:block}
.myth-truth,.case-notes,.faq,.final-cta{padding:2rem 0}
.myth-list{list-style:none;padding:0}
.myth-list li{background:#fff;border:1px solid #eef6f5;padding:1rem;border-radius:10px;margin-bottom:.6rem}
.myth-list .truth{color:var(--muted);margin:0}
.case-notes ol{padding-left:1.2rem}
.case-notes .disclaimer{font-size:.85rem;color:var(--muted)}
.faq .qa{margin-bottom:.6rem}
.faq .q{width:100%;text-align:left;padding:.8rem;border-radius:10px;border:1px solid #eef6f5;background:#fff}
.faq .a{display:none;padding:.6rem;border-left:3px solid var(--accent);background:#fbfdfc;border-radius:0 8px 8px 8px}
.final-cta .primary.large{padding:1rem 1.4rem;border-radius:12px}
.site-footer{border-top:1px solid #eef6f5;padding:1rem 0;margin-top:2rem}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}
.reveal{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
.reveal.is-visible{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none}
}
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .pillars .grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Date in footer
  document.getElementById('year').textContent = new Date().getFullYear();

  // Simple reveal on scroll with prefers-reduced-motion support
  var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var reveals = document.querySelectorAll('.reveal');
  function show(el){ el.classList.add('is-visible'); }
  if(prefersReduced){ reveals.forEach(show); }
  else if('IntersectionObserver' in window){
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if(e.isIntersecting) { show(e.target); io.unobserve(e.target); }
      });
    },{rootMargin:'-10% 0px',threshold:0.08});
    reveals.forEach(function(r){ io.observe(r); });
  } else { reveals.forEach(show); }

  // FAQ toggles
  document.querySelectorAll('.faq .q').forEach(function(btn){
    btn.addEventListener('click',function(){
      var a = this.nextElementSibling;
      var visible = a.style.display === 'block';
      document.querySelectorAll('.faq .a').forEach(function(x){ x.style.display = 'none'; });
      a.style.display = visible ? 'none' : 'block';
    });
  });

  // Session Planner
  var form = document.getElementById('planner-form');
  var buildBtn = document.getElementById('build-plan');
  var copyBtn = document.getElementById('copy-plan');
  var output = document.getElementById('plan-output');

  function gather(){
    var data = {};
    var f = new FormData(form);
    data.focus = f.get('focus') || '';
    data.routine = f.get('routine') || '';
    data.obstacle = f.get('obstacle') || '';
    data.time = f.get('time') || '';
    data.style = f.get('style') || '';
    return data;
  }

  function buildText(d){
    var lines = [];
    lines.push('Personal session plan');
    lines.push('---------------------');
    if(d.focus) lines.push('Focus: ' + d.focus);
    if(d.routine) lines.push('Routine note: ' + d.routine);
    if(d.obstacle) lines.push('Biggest obstacle: ' + d.obstacle);
    lines.push('Weekly time commitment: ' + d.time);
    lines.push('Preferred approach: ' + (d.style === 'learning' ? 'Cohort + learning' : 'Guided plan'));
    lines.push('');
    lines.push('Suggested first steps:');
    if(d.focus.match(/sleep|bed/i)){
      lines.push('- Establish two simple evening anchors (lighting, 20-min wind-down).');
    } else if(d.focus.match(/digest|gut|stomach/i)){
      lines.push('- Try a 3-day gentle food log and one timing adjustment.');
    } else {
      lines.push('- Pick one small experiment to try for 1 week tied to energy or routine.');
    }
    lines.push('- Schedule a 20–30 minute check-in in 10–14 days to review how it went.');
    lines.push('');
    lines.push('Notes: This is educational guidance, not a diagnosis. Share with your healthcare team as needed.');
    return lines.join('\n');
  }

  buildBtn.addEventListener('click', function(){
    var data = gather();
    if(!data.focus){ output.value = 'Please add a short focus to build a plan.'; return; }
    output.value = buildText(data);
    // focus animation to show output
    output.scrollIntoView({behavior: 'smooth', block: 'center'});
  });

  copyBtn.addEventListener('click', function(){
    if(!output.value){ alert('No plan to copy — build a plan first.'); return; }
    navigator.clipboard.writeText(output.value).then(function(){
      copyBtn.textContent = 'Copied!';
      setTimeout(function(){ copyBtn.textContent = 'Copy summary'; },1500);
    }, function(){
      alert('Could not copy to clipboard.');
    });
  });

})();
"} 
